# Deploy automatizado com blue-green deployment
set -euo pipefail

APP_NAME="${APP_NAME:-myapp}"
DOCKER_REGISTRY="${DOCKER_REGISTRY:-registry.example.com}"
CURRENT_COLOR_FILE="/var/lib/deployment/current_color"

get_current_color() {
    [[ -f "$CURRENT_COLOR_FILE" ]] && cat "$CURRENT_COLOR_FILE" || echo "blue"
}

get_next_color() { [[ "$1" == "blue" ]] && echo "green" || echo "blue"; }

deploy() {
    local version="${1:-latest}"
    local current=$(get_current_color)
    local next=$(get_next_color "$current")
    local image="$DOCKER_REGISTRY/$APP_NAME:$version"

    echo "Deploy: $version ($current → $next)"

    docker pull "$image"
    docker stop "${APP_NAME}_${next}" 2>/dev/null || true
    docker rm "${APP_NAME}_${next}" 2>/dev/null || true

    [[ "$next" == "blue" ]] && local port=8080 || local port=8081

    docker run -d --name "${APP_NAME}_${next}" \
        -p "${port}:8080" -e "COLOR=$next" "$image"

    # Health check
    for i in {1..30}; do
        curl -sf "http://localhost:$port/health" && break
        sleep 2
    done

    # Switch proxy
    cat > /etc/nginx/conf.d/app.conf << EOF
