#!/usr/bin/env python3
"""Parser de logs com agrupamento inteligente de erros."""
import re
import hashlib
import json
from collections import defaultdict
from datetime import datetime

class LogGrouper:
    """Agrupa logs similares usando hash de stack trace normalizado."""

    def __init__(self):
        self.error_groups = defaultdict(lambda: {
            'count': 0, 'first_seen': None, 'last_seen': None, 'samples': []
        })
        self.hash_patterns = {
            'uuid': r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}',
            'hex_id': r'0x[0-9a-f]+',
            'number': r'\d+',
            'timestamp': r'\d{4}-\d{2}-\d{2}[\sT]\d{2}:\d{2}:\d{2}'
        }

    def normalize_trace(self, trace):
        """Remove valores variáveis do stack trace."""
        normalized = trace
        for name, pattern in self.hash_patterns.items():
            normalized = re.sub(pattern, f'{{{{{name}}}}}', normalized)
        return normalized

    def compute_hash(self, trace):
        """Gera hash do stack trace normalizado."""
        normalized = self.normalize_trace(trace)
        return hashlib.md5(normalized.encode()).hexdigest()[:12]

    def add_error(self, log_entry):
        """Adiciona um erro ao agrupamento."""
        error_hash = self.compute_hash(log_entry)
        group = self.error_groups[error_hash]
        group['count'] += 1
        now = datetime.now().isoformat()
        if group['first_seen'] is None:
            group['first_seen'] = now
        group['last_seen'] = now
        if len(group['samples']) < 3:
            group['samples'].append(log_entry)
        return error_hash

    def generate_report(self):
        """Gera relatório de erros agrupados."""
        report = {
            'generated_at': datetime.now().isoformat(),
            'total_unique_errors': len(self.error_groups),
            'total_occurrences': sum(g['count'] for g in self.error_groups.values()),
            'errors': []
        }
        for error_hash, data in sorted(
            self.error_groups.items(), key=lambda x: x[1]['count'], reverse=True
        ):
            report['errors'].append({
                'error_id': error_hash,
                'occurrences': data['count'],
                'first_seen': data['first_seen'],
                'last_seen': data['last_seen'],
                'sample': data['samples'][0] if data['samples'] else None
            })
        return report

# Exemplo de uso
if __name__ == '__main__':
    grouper = LogGrouper()
    sample_logs = [
        '2024-04-13 10:30:15 [ERROR] db: Connection timeout to db-01',
        '2024-04-13 10:31:22 [ERROR] db: Connection timeout to db-02',
        '2024-04-13 10:35:00 [ERROR] api: KeyError: user_id not found',
    ]
    for log in sample_logs:
        grouper.add_error(log)
    print(json.dumps(grouper.generate_report(), indent=2))
```

**O que é Circuit Breaker:**

Circuit Breaker é um padrão que previne falhas em cascata. Se um serviço externo está falhando repetidamente, o circuit breaker "abre" e falha rápido.

**Estados:**
- **CLOSED**: Funcionamento normal, requisições passam
- **OPEN**: Serviço com falha, rejeita requisições imediatamente
- **HALF_OPEN**: Testando se serviço recuperou

```python
#!/usr/bin/env python3
"""Circuit Breaker para APIs externas."""
import time
import threading
from enum import Enum, auto
from functools import wraps

class CircuitState(Enum):
    CLOSED = auto()
    OPEN = auto()
    HALF_OPEN = auto()

class CircuitBreaker:
    def __init__(self, failure_threshold=5, recovery_timeout=30,
                 expected_exception=(Exception,), success_threshold=2):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.expected_exception = expected_exception
        self.success_threshold = success_threshold
        self._state = CircuitState.CLOSED
        self._failure_count = 0
        self._success_count = 0
        self._last_failure_time = None
        self._lock = threading.Lock()

    @property
    def state(self):
        with self._lock:
            return self._state

    def _can_attempt_reset(self):
        if self._last_failure_time is None:
            return False
        return time.time() - self._last_failure_time >= self.recovery_timeout

    def call(self, func, *args, **kwargs):
        with self._lock:
            if self._state == CircuitState.OPEN:
                if self._can_attempt_reset():
                    self._state = CircuitState.HALF_OPEN
                    self._success_count = 0
                else:
                    raise CircuitBreakerOpenException(
                        f'Circuito ABERTO. Tente em {self.recovery_timeout}s')

        try:
            result = func(*args, **kwargs)
            self._on_success()
            return result
        except self.expected_exception as e:
            self._on_failure()
            raise

    def _on_success(self):
        with self._lock:
            if self._state == CircuitState.HALF_OPEN:
                self._success_count += 1
                if self._success_count >= self.success_threshold:
                    self._reset()
            else:
                self._failure_count = 0

    def _on_failure(self):
        with self._lock:
            self._failure_count += 1
            self._last_failure_time = time.time()
            if self._failure_count >= self.failure_threshold:
                self._state = CircuitState.OPEN

    def _reset(self):
        self._state = CircuitState.CLOSED
        self._failure_count = 0
        self._success_count = 0
        self._last_failure_time = None

    def __call__(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return self.call(func, *args, **kwargs)
        return wrapper

class CircuitBreakerOpenException(Exception):
    pass

import requests
payment_circuit = CircuitBreaker(failure_threshold=3, recovery_timeout=60,
                                 expected_exception=(requests.RequestException,))

@payment_circuit
def process_payment(amount, user_id):
    response = requests.post('https://api.payment-gateway.com/v1/charge',
                             json={'amount': amount, 'user_id': user_id}, timeout=10)
    response.raise_for_status()
    return response.json()

# Uso com fallback
def process_payment_safe(amount, user_id):
    try:
        return process_payment(amount, user_id)
    except CircuitBreakerOpenException:
        print(f'[FALLBACK] Pagamento {amount} enfileirado')
        return {'status': 'queued'}
```

