#!/usr/bin/env python3
"""API Flask com autenticação JWT."""
from flask import Flask, jsonify, request
from functools import wraps
import jwt
import datetime
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.config['SECRET_KEY'] = 'sua-chave-secreta-muito-segura'

# Simulação de banco de dados
users = {
    'admin': generate_password_hash('senha123')
}

def token_required(f):
    """Decorator que exige token JWT válido."""
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'message': 'Token ausente!'}), 401

        try:
            # Remover 'Bearer ' se presente
            if token.startswith('Bearer '):
                token = token.split(' ')[1]
            data = jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])
            current_user = data['user']
        except jwt.ExpiredSignatureError:
            return jsonify({'message': 'Token expirado!'}), 401
        except jwt.InvalidTokenError:
            return jsonify({'message': 'Token inválido!'}), 401

        return f(current_user, *args, **kwargs)
    return decorated

@app.route('/login', methods=['POST'])
def login():
    """Endpoint de login que gera token JWT."""
    auth = request.get_json()
    username = auth.get('username')
    password = auth.get('password')

    if not username or not password:
        return jsonify({'message': 'Credenciais incompletas!'}), 401

    if username not in users:
        return jsonify({'message': 'Usuário não encontrado!'}), 401

    if not check_password_hash(users[username], password):
        return jsonify({'message': 'Senha incorreta!'}), 401

    token = jwt.encode({
        'user': username,
        'exp': datetime.datetime.utcnow() + datetime.timedelta(hours=24)
    }, app.config['SECRET_KEY'], algorithm='HS256')

    return jsonify({'token': token, 'exp': '24h'})

@app.route('/protected', methods=['GET'])
@token_required
def protected_route(current_user):
    """Rota protegida que requer token válido."""
    return jsonify({
        'message': f'Olá {current_user}, você acessou uma rota protegida!',
        'user': current_user
    })

@app.route('/refresh', methods=['POST'])
@token_required
def refresh_token(current_user):
    """Renova token antes de expirar."""
    new_token = jwt.encode({
        'user': current_user,
        'exp': datetime.datetime.utcnow() + datetime.timedelta(hours=24)
    }, app.config['SECRET_KEY'], algorithm='HS256')
    return jsonify({'token': new_token})

if __name__ == '__main__':
    app.run(debug=True)
