**Padrão Strategy:**

O padrão Strategy permite definir uma família de algoritmos, encapsulá-los e torná-los intercambiáveis. O Strategy permite que o algoritmo varie independentemente dos clientes que o usam.

**Exemplo 1: Sistema de Pagamento**
```python
from abc import ABC, abstractmethod
from typing import Protocol

class PaymentStrategy(ABC):
    """Interface base para estratégias de pagamento."""

    @abstractmethod
    def pay(self, amount: float) -> str:
        pass

    @abstractmethod
    def validate(self) -> bool:
        pass

class CreditCardStrategy(PaymentStrategy):
    def __init__(self, card_number: str, cvv: str, expiry: str):
        self.card_number = card_number
        self.cvv = cvv
        self.expiry = expiry

    def validate(self) -> bool:
        return len(self.card_number) == 16 and len(self.cvv) == 3

    def pay(self, amount: float) -> str:
        if not self.validate():
            return "Cartão inválido"
        last_four = self.card_number[-4:]
        return f"Pagamento de R${amount:.2f} via cartão ****{last_four}"

class PayPalStrategy(PaymentStrategy):
    def __init__(self, email: str, password: str):
        self.email = email
        self.password = password

    def validate(self) -> bool:
        return '@' in self.email and len(self.password) >= 6

    def pay(self, amount: float) -> str:
        return f"Pagamento de R${amount:.2f} via PayPal ({self.email})"

class PixStrategy(PaymentStrategy):
    def __init__(self, pix_key: str):
        self.pix_key = pix_key

    def validate(self) -> bool:
        return len(self.pix_key) > 0

    def pay(self, amount: float) -> str:
        return f"Pagamento de R${amount:.2f} via PIX (chave: {self.pix_key[:10]}...)"

class ShoppingCart:
    """Contexto que usa uma estratégia de pagamento."""

    def __init__(self):
        self.items = []
        self._payment_strategy: PaymentStrategy | None = None

    def add_item(self, name: str, price: float):
        self.items.append({'name': name, 'price': price})

    def set_payment_strategy(self, strategy: PaymentStrategy):
        self._payment_strategy = strategy

    def calculate_total(self) -> float:
        return sum(item['price'] for item in self.items)

    def checkout(self) -> str:
        if not self._payment_strategy:
            return "Erro: método de pagamento não selecionado"

        total = self.calculate_total()
        return self._payment_strategy.pay(total)

# Uso
cart = ShoppingCart()
cart.add_item("Notebook", 4500.00)
cart.add_item("Mouse", 150.00)

# Trocar estratégias em tempo de execuçãocart.set_payment_strategy(CreditCardStrategy("1234567890123456", "123", "12/25"))
print(cart.checkout())

cart.set_payment_strategy(PixStrategy("user@email.com"))
print(cart.checkout())
```

**Exemplo 2: Compressão de Arquivos**
```python
import gzip
import zipfile
import bz2
from pathlib import Path

class CompressionStrategy(ABC):
    @abstractmethod
    def compress(self, data: bytes, output_path: Path):
        pass

    @abstractmethod
    def decompress(self, input_path: Path) -> bytes:
        pass

class GzipStrategy(CompressionStrategy):
    def compress(self, data: bytes, output_path: Path):
        with gzip.open(output_path, 'wb') as f:
            f.write(data)

    def decompress(self, input_path: Path) -> bytes:
        with gzip.open(input_path, 'rb') as f:
            return f.read()

class Bzip2Strategy(CompressionStrategy):
    def compress(self, data: bytes, output_path: Path):
        with bz2.open(output_path, 'wb') as f:
            f.write(data)

    def decompress(self, input_path: Path) -> bytes:
        with bz2.open(input_path, 'rb') as f:
            return f.read()

# Factory para escolher estratégia
def get_compression_strategy(algorithm: str) -> CompressionStrategy:
    strategies = {
        'gzip': GzipStrategy(),
        'bzip2': Bzip2Strategy(),
    }
    return strategies.get(algorithm, GzipStrategy())
