from tenacity import retry, stop_after_attempt, wait_exponential, retry_if_exception_type

class LLMRateLimitError(Exception): pass
class AgentTimeoutError(Exception): pass

@retry(
    stop=stop_after_attempt(3),
    wait=wait_exponential(multiplier=1, min=2, max=30),
    retry=retry_if_exception_type((LLMRateLimitError, AgentTimeoutError))
)
async def call_agent(agent, prompt):
    try:
        return await agent.ainvoke(prompt)
    except RateLimitError:
        raise LLMRateLimitError('Rate limit')
    except asyncio.TimeoutError:
        raise AgentTimeoutError('Timeout')

