class TaskDispatcher:
    def __init__(self):
        self.queue = asyncio.PriorityQueue()
        self.agents = {'researcher': [], 'coder': [], 'analyst': []}
    async def submit(self, task): await self.queue.put(task)
    async def dispatch(self):
        while True:
            task = await self.queue.get()
            available = [a for a in self.agents[task.agent_type] if not a.busy]
            if available:
                asyncio.create_task(available[0].process(task))
            else:
                await self.queue.put(task)
                await asyncio.sleep(1)

