import hashlib, json
from datetime import datetime, timedelta

class AgentCache:
    def __init__(self, ttl_seconds=3600):
        self.cache = {}
        self.ttl = timedelta(seconds=ttl_seconds)
    def _key(self, agent_id, input_data):
        serialized = json.dumps({'agent': agent_id, 'input': input_data}, sort_keys=True)
        return hashlib.sha256(serialized.encode()).hexdigest()
    def get(self, agent_id, input_data):
        key = self._key(agent_id, input_data)
        if key in self.cache:
            result, ts = self.cache[key]
            if datetime.now() - ts < self.ttl: return result
            del self.cache[key]
        return None
    def set(self, agent_id, input_data, result):
        self.cache[self._key(agent_id, input_data)] = (result, datetime.now())

class CachedAgent:
    def __init__(self, agent_id, agent, cache):
        self.agent_id = agent_id; self.agent = agent; self.cache = cache
    async def run(self, input_data):
        cached = self.cache.get(self.agent_id, input_data)
        if cached is not None: return cached
        result = await self.agent.ainvoke(input_data)
        self.cache.set(self.agent_id, input_data, result)
        return result

Use hashing deterministico (JSON sorted keys). TTL evita resultados stale. Cache compartilhado permite cross-agent hits.

from pydantic import BaseModel, Field, ValidationError
