import asyncio
from dataclasses import dataclass
from typing import Any, Callable

@dataclass
class Message:
    sender: str; recipient: str; content: Any; msg_type: str

class MessageBus:
    def __init__(self):
        self.queues = {}; self.handlers = {}
    def register(self, agent_id, handler):
        self.queues[agent_id] = asyncio.Queue(); self.handlers[agent_id] = handler
    async def send(self, msg): await self.queues[msg.recipient].put(msg)
    async def broadcast(self, sender, content, msg_type):
        for aid in self.queues:
            if aid != sender: await self.queues[aid].put(Message(sender, aid, content, msg_type))
    async def run_agent(self, agent_id):
        while True:
            msg = await self.queues[agent_id].get()
            response = await self.handlers[agent_id](msg)
            if response: await self.send(response)

Vantagem: desacoplamento total. Desvantagem: debugging mais dificil (mensagens assincronas, ordem varia).

from langgraph.graph import StateGraph, START, END
from langgraph.types import Command
from typing import Literal

class ReflexionState(TypedDict):
    task: str; draft: str; critique: str; iteration: int; max_iterations: int

def generator(state):
    if state.get('iteration', 0) == 0:
        draft = generate(state['task'])
    else:
        draft = generate(f'{state["task"]}\nCritica anterior: {state["critique"]}')
    return {'draft': draft, 'iteration': state.get('iteration', 0) + 1}

def critic(state):
    critique = evaluate(f'Tarefa: {state["task"]}\nResposta: {state["draft"]}')
    return {'critique': critique}

def should_continue(state) -> Literal['generator', '__end__']:
    if state.get('iteration', 0) >= state.get('max_iterations', 3): return '__end__'
    if 'APROVADO' in state.get('critique', ''): return '__end__'
    return 'generator'

builder = StateGraph(ReflexionState)
builder.add_node('generator', generator)
builder.add_node('critic', critic)
builder.add_edge(START, 'generator')
builder.add_edge('generator', 'critic')
builder.add_conditional_edges('critic', should_continue)

Padrao: Generator->Critic->(rejeitado->Generator->Critic->...)->(aprovado ou max_iterations)->END.

from langgraph.graph import StateGraph, MessagesState, START, END
from langgraph.types import Command
from langchain_core.messages import AIMessage, HumanMessage, SystemMessage

class SharedContextState(MessagesState):
    current_agent: str; context_summary: str

def summarize_context(messages, max_messages=20):
    if len(messages) <= max_messages: return None
    recent = messages[-max_messages:]
    return f'Contexto: {len(messages)} mensagens anteriores. Ultimas: {[m.content[:50] for m in recent[-3:]]}'

def agent_node(agent_id, system_prompt):
    def node(state):
        messages = state['messages']
        summary = summarize_context(messages)
        if summary:
            messages = [SystemMessage(content=summary)] + messages[-10:]
        response = call_llm([SystemMessage(content=system_prompt)] + messages)
        return {'messages': [AIMessage(content=response)], 'current_agent': agent_id}
    return node

O contexto e compartilhado via messages. Quando fica grande demais, um sumario e gerado e prefixado como SystemMessage. Isso evita estourar o context window mantendo coerencia.

from langgraph.graph import StateGraph, MessagesState, START, END
from langgraph.types import Command
from langchain_core.messages import AIMessage

class HierarchicalState(MessagesState):
    tasks: list[dict]; results: dict; current_task: int

def manager(state):
    if not state.get('tasks'):
        tasks = decompose(state['messages'][-1].content)
        return {'tasks': tasks, 'current_task': 0}
    completed = len(state.get('results', {}))
    total = len(state['tasks'])
    if completed >= total:
        final = synthesize(state['results'])
        return {'messages': [AIMessage(content=final)]}
    task = state['tasks'][state['current_task']]
    return Command(goto=task['agent'], update={'current_task': state['current_task'] + 1})

def researcher(state):
    task = state['tasks'][state['current_task'] - 1]
    result = do_research(task['description'])
    results = {**state.get('results', {}), task['id']: result}
    return Command(goto='manager', update={'results': results})

Gerente: divide, delega, monitora e sintetiza. Subordinados: executam e reportam. Vantagem: escalabilidade. Desvantagem: gerente e ponto unico de falha.

O padrao blackboard usa um espaco compartilhado onde agentes leem e escrevem, sem comunicacao direta:

import asyncio
from datetime import datetime

class Blackboard:
    def __init__(self):
        self.data = {}; self.lock = asyncio.Lock()
    async def write(self, key, value, agent_id):
        async with self.lock:
            self.data[key] = {'value': value, 'author': agent_id, 'ts': datetime.now().isoformat()}
    async def read(self, key): return self.data.get(key, {}).get('value')
    async def read_all(self): return dict(self.data)

class BlackboardAgent:
    def __init__(self, agent_id, blackboard, interests, contributions):
        self.agent_id = agent_id; self.bb = blackboard
        self.interests = interests; self.contributions = contributions
    async def run(self):
        while True:
            data = await self.bb.read_all()
            if all(k in data for k in self.interests):
                result = process(data, self.contributions)
                for k, v in result.items(): await self.bb.write(k, v, self.agent_id)
                break
            await asyncio.sleep(0.5)

Vantagem: desacoplamento total (agentes nao se conhecem). Desvantagem: ordem nao garantida, polling necessario.

import asyncio, time
from enum import Enum

class CircuitState(Enum):
    CLOSED = 'closed'; OPEN = 'open'; HALF_OPEN = 'half_open'

class CircuitBreaker:
    def __init__(self, failure_threshold=3, recovery_timeout=30):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.state = CircuitState.CLOSED
        self.failure_count = 0; self.last_failure_time = 0
    async def call(self, func, *args, **kwargs):
        if self.state == CircuitState.OPEN:
            if time.time() - self.last_failure_time > self.recovery_timeout:
                self.state = CircuitState.HALF_OPEN
            else:
                raise Exception('Circuit breaker OPEN')
        try:
            result = await func(*args, **kwargs)
            if self.state == CircuitState.HALF_OPEN:
                self.state = CircuitState.CLOSED; self.failure_count = 0
            return result
        except Exception:
            self.failure_count += 1; self.last_failure_time = time.time()
            if self.failure_count >= self.failure_threshold:
                self.state = CircuitState.OPEN
            raise

Estados: CLOSED (normal), OPEN (falhou N vezes, rejeita), HALF_OPEN (teste se recuperou). Use um breaker por agente.

Especialistas: Prompt focado em UM dominio. Maior qualidade. Menos hallucination. Mais agentes para gerenciar. Exemplo: researcher, coder, analyst, writer.

Generalistas: Prompt amplo cobrindo multiplos dominios. Flexivel. Mais propenso a hallucination. Menos agentes. Exemplo: agente unico com roteamento interno.

Hibrido (melhor dos dois): Queries simples vao para generalista. Queries complexas roteam para especialistas.

